arguments.new_str:
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddScoped<IUserService, UserService>();
// Breaking change 1: ValidateScopes is now enabled in ALL environments (not
// just Development). A singleton must not capture a scoped service from the
// root provider. Inject IServiceScopeFactory instead and resolve per-use.
builder.Services.AddSingleton<ICacheService>(sp =>
    new CacheService(sp.GetRequiredService<IServiceScopeFactory>()));
// Breaking change 2: ConfigureHttpMessageHandlerBuilder was removed in .NET 9.
// Use ConfigurePrimaryHttpMessageHandler instead.
builder.Services.AddHttpClient("api")
    .ConfigurePrimaryHttpMessageHandler(() =>
    {
        return new HttpClientHandler { UseCookies = false };
    });
// Breaking change 3: IHttpClientFactory now redacts all HTTP header values in
// logs by default. To keep Trace-level header debugging working, explicitly
// clear the redacted-header set so values are logged in full.
builder.Services.ConfigureAll<HttpClientFactoryOptions>(options =>
{
    options.RedactedLoggedHeaders.Clear();
});
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
});
var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

